#include "core/fusion_pass.hpp"
#include "core/workspace_packer.hpp"
#include "tests/universal_fixture.hpp"
#include <cstdio>
#include <cstdlib>
#include <string>
#include <utility>
#include <unordered_set>
#include <unistd.h>
using namespace universal;
#define CHECK(x) do { if(!(x)){std::fprintf(stderr,"check failed: %s:%d %s\n",__FILE__,__LINE__,#x);return 1;} } while(0)
int main(){
 const universal_test::FixtureFamily fixtures[]={universal_test::FixtureFamily::Dense,universal_test::FixtureFamily::MoE,universal_test::FixtureFamily::Hybrid,universal_test::FixtureFamily::MLA};
 const Family expected[]={Family::DenseGQA,Family::PureMoE,Family::HybridGDNMoE,Family::SparseMLAMoE};
 for(size_t f=0;f<4;++f){const std::string path=universal_test::write_tiny_gguf(fixtures[f]);CHECK(!path.empty());
  vegajet::GgufFile gg;CHECK(gg.open(path));for(uint32_t tp=1;tp<=4;++tp)for(auto hw:{std::pair<uint32_t,uint32_t>{60,16},{60,32},{64,32}}){Options opt;opt.tp_size=tp;opt.n_cu=hw.first;Model m=lower_gguf(gg,opt);CHECK(m.valid()&&m.family==expected[f]&&m.tensors.size()>=1&&m.hidden==64&&m.layers==2&&m.heads==4&&m.kv_heads==2&&m.head_dim==16);CHECK(m.tensors[0].shape.dims.size()==2&&m.tensors[0].shape.elements()==4096);auto graph_plan=pack_workspace(m,{opt.m,512});CHECK(graph_plan.valid()&&graph_plan.arena_bytes%(2ull*1024*1024)==0);for(const auto&b:graph_plan.buffers)CHECK(b.offset%256==0);for(size_t step=0;step<m.ops.size();++step)CHECK(workspace_overlap_free(graph_plan,step));auto verify_graph=[&](){std::unordered_set<size_t> defs{m.input_value};for(const auto&o:m.ops){for(size_t in:o.inputs)if(defs.count(in)==0)return false;for(size_t out:o.outputs)if(!defs.insert(out).second)return false;}return true;};CHECK(verify_graph());for(const auto&o:m.ops)if(o.kind==OpKind::ResidualAdd)CHECK(o.inputs.size()==2);
   PassManager pm;auto st=pm.run(m,{tp,hw.first,1,false});CHECK(st.elided_allreduce==(tp==1?2:0)); // allreduce nodes are explicit until this pass
   CHECK(st.qkv_cache==(f==2?1:2));CHECK(st.reductions==2);CHECK(st.moe==(f==0?0:2));CHECK(verify_graph());for(const auto&o:m.ops){const bool weight=o.kind==OpKind::Linear||o.kind==OpKind::MoEFFN;if(weight)CHECK(o.glc&&o.slc&&o.cache==CachePolicy::Streaming&&o.grid_x==4*hw.first);else CHECK(!o.glc&&!o.slc&&o.cache==CachePolicy::Default);}
  }{Model big_model=lower_gguf(gg,Options{});auto big_plan=pack_workspace(big_model,{512,131072});CHECK(big_plan.valid()&&big_plan.arena_bytes<big_plan.naive_bytes);}if(f==0){Model workspace_model=lower_gguf(gg,Options{});for(uint32_t wm:{1u,2u,16u,64u,256u,512u})for(uint64_t ws:{512ull,4096ull,131072ull}){auto plan=pack_workspace(workspace_model,{wm,ws});CHECK(plan.valid());for(size_t step=0;step<workspace_model.ops.size();++step)CHECK(workspace_overlap_free(plan,step));}Options opt;opt.tp_size=2;opt.n_cu=64;opt.m=2;auto m=lower_gguf(gg,opt);PassManager pm;for(uint32_t hit=2;hit<=16;++hit){pm.run(m,{2,64,hit,false});for(const auto&o:m.ops){const bool weight=o.kind==OpKind::Linear||o.kind==OpKind::MoEFFN;CHECK(!o.glc&&!o.slc);CHECK(o.cache==(weight?CachePolicy::Temporal:CachePolicy::Default));if(hit==2&&weight)CHECK(o.grid_x==256&&o.grid_y==2&&o.split_k==1);}}pm.run(m,{2,60,64,true});for(const auto&o:m.ops){const bool weight=o.kind==OpKind::Linear||o.kind==OpKind::MoEFFN;if(weight)CHECK(o.grid_y==64);CHECK(!o.glc&&!o.slc&&o.cache==(weight?CachePolicy::Temporal:CachePolicy::Default));}}::unlink(path.c_str());}
 for(uint32_t m: {1u,2u,16u,64u,256u,512u})for(uint64_t seq:{512ull,4096ull,131072ull}){std::vector<BufferRequest> r={{"a",0,1,{8192,1,false,false}},{"b",2,3,{8192,1,false,false}},{"c",4,5,{1,1,true,false}}};auto p=pack_workspace(r,{m,seq});CHECK(p.valid());if(m==512&&seq==131072)CHECK(p.arena_bytes<p.naive_bytes);for(size_t step=0;step<6;++step)CHECK(workspace_overlap_free(p,step));}
 std::vector<BufferRequest> fuzz;for(size_t i=0;i<48;++i){const size_t birth=(i*7)%32;const size_t death=birth+(i*11)%((32-birth)+1);fuzz.push_back({"scratch",birth,death,{static_cast<uint64_t>(1+(i*97)%8192),1,false,false}});}auto fuzz_plan=pack_workspace(fuzz,{64,8192});CHECK(fuzz_plan.valid());for(size_t step=0;step<32;++step)CHECK(workspace_overlap_free(fuzz_plan,step));
 auto bad=pack_workspace({{"bad",2,1,{1,1,false,false}}},{1,512});CHECK(!bad.valid());CHECK(!pack_workspace(std::vector<BufferRequest>{}, {17,512}).valid());
 vjtest::GgufWriter missing;missing.kv_str("general.architecture","fixture");missing.kv_u32("fixture.embedding_length",64);missing.kv_u32("fixture.block_count",1);missing.kv_u32("fixture.attention.head_count",4);auto missing_path=universal_test::write_gguf(missing);CHECK(!missing_path.empty());vegajet::GgufFile missing_gguf;CHECK(missing_gguf.open(missing_path));CHECK(!lower_gguf(missing_gguf).valid());::unlink(missing_path.c_str());
 vjtest::GgufWriter malformed;malformed.kv_str("general.architecture","fixture");malformed.kv_u32("fixture.embedding_length",64);malformed.kv_u32("fixture.block_count",1);malformed.kv_u32("fixture.attention.head_count",4);malformed.tensor("blk.0.attn_q.weight",{0},0,{});auto malformed_path=universal_test::write_gguf(malformed);CHECK(!malformed_path.empty());vegajet::GgufFile malformed_gguf;CHECK(malformed_gguf.open(malformed_path));CHECK(!lower_gguf(malformed_gguf).valid());::unlink(malformed_path.c_str());std::puts("[PASS] universal compiler family/TP/hardware, cache/fusion and workspace matrix");return 0;
}
